17	package com.google.zxing.client.result;
18	
19	import com.google.zxing.Result;
20	
21	import java.io.UnsupportedEncodingException;
22	import java.net.URLDecoder;
23	import java.util.ArrayList;
24	import java.util.HashMap;
25	import java.util.List;
26	import java.util.Map;
27	import java.util.regex.Pattern;
28	
29	/**
30	 * <p>Abstract class representing the result of decoding a barcode, as more than
31	 * a String -- as some type of structured data. This might be a subclass which represents
32	 * a URL, or an e-mail address. {@link #parseResult(Result)} will turn a raw
33	 * decoded string into the most appropriate type of structured representation.</p>
34	 *
35	 * <p>Thanks to Jeff Griffin for proposing rewrite of these classes that relies less
36	 * on exception-based mechanisms during parsing.</p>
37	 *
38	 * @author Sean Owen
39	 */
40	public abstract class ResultParser {
41	
42	  private static final ResultParser[] PARSERS = {
43	      new BookmarkDoCoMoResultParser(),
44	      new AddressBookDoCoMoResultParser(),
45	      new EmailDoCoMoResultParser(),
46	      new AddressBookAUResultParser(),
47	      new VCardResultParser(),
48	      new BizcardResultParser(),
49	      new VEventResultParser(),
50	      new EmailAddressResultParser(),
51	      new SMTPResultParser(),
52	      new TelResultParser(),
53	      new SMSMMSResultParser(),
54	      new SMSTOMMSTOResultParser(),
55	      new GeoResultParser(),
56	      new WifiResultParser(),
57	      new URLTOResultParser(),
58	      new URIResultParser(),
59	      new ISBNResultParser(),
60	      new ProductResultParser(),
61	      new ExpandedProductResultParser(),
62	      new VINResultParser(),
63	  };
64	
65	  private static final Pattern DIGITS = Pattern.compile("\\d+");
66	  private static final Pattern AMPERSAND = Pattern.compile("&");
67	  private static final Pattern EQUALS = Pattern.compile("=");
68	  private static final String BYTE_ORDER_MARK = "\ufeff";
69	
70	  static final String[] EMPTY_STR_ARRAY = new String[0];
71	
72	  /**
73	   * Attempts to parse the raw {@link Result}'s contents as a particular type
74	   * of information (email, URL, etc.) and return a {@link ParsedResult} encapsulating
75	   * the result of parsing.
76	   *
77	   * @param theResult the raw {@link Result} to parse
78	   * @return {@link ParsedResult} encapsulating the parsing result
79	   */
80	  public abstract ParsedResult parse(Result theResult);
81	
82	  protected static String getMassagedText(Result result) {
83	    String text = result.getText();
84	    if (text.startsWith(BYTE_ORDER_MARK)) {
85	      text = text.substring(1);
86	    }
87	    return text;
88	  }
89	
90	  public static ParsedResult parseResult(Result theResult) {
91	    for (ResultParser parser : PARSERS) {
92	      ParsedResult result = parser.parse(theResult);
93	      if (result != null) {
94	        return result;
95	      }
96	    }
97	    return new TextParsedResult(theResult.getText(), null);
98	  }
99	
100	  protected static void maybeAppend(String value, StringBuilder result) {
101	    if (value != null) {
102	      result.append('\n');
103	      result.append(value);
104	    }
105	  }
106	
107	  protected static void maybeAppend(String[] value, StringBuilder result) {
108	    if (value != null) {
109	      for (String s : value) {
110	        result.append('\n');
111	        result.append(s);
112	      }
113	    }
114	  }
115	
116	  protected static String[] maybeWrap(String value) {
117	    return value == null ? null : new String[] { value };
118	  }
119	
120	  protected static String unescapeBackslash(String escaped) {
121	    int backslash = escaped.indexOf('\\');
122	    if (backslash < 0) {
123	      return escaped;
124	    }
125	    int max = escaped.length();
126	    StringBuilder unescaped = new StringBuilder(max - 1);
127	    unescaped.append(escaped.toCharArray(), 0, backslash);
128	    boolean nextIsEscaped = false;
129	    for (int i = backslash; i < max; i++) {
130	      char c = escaped.charAt(i);
131	      if (nextIsEscaped || c != '\\') {
132	        unescaped.append(c);
133	        nextIsEscaped = false;
134	      } else {
135	        nextIsEscaped = true;
136	      }
137	    }
138	    return unescaped.toString();
139	  }
140	
141	  protected static int parseHexDigit(char c) {
142	    if (c >= '0' && c <= '9') {
143	      return c - '0';
144	    }
145	    if (c >= 'a' && c <= 'f') {
146	      return 10 + (c - 'a');
147	    }
148	    if (c >= 'A' && c <= 'F') {
149	      return 10 + (c - 'A');
150	    }
151	    return -1;
152	  }
153	
154	  protected static boolean isStringOfDigits(CharSequence value, int length) {
155	    return value != null && length > 0 && length == value.length() && DIGITS.matcher(value).matches();
156	  }
157	
158	  protected static boolean isSubstringOfDigits(CharSequence value, int offset, int length) {
159	    if (value == null || length <= 0) {
160	      return false;
161	    }
162	    int max = offset + length;
163	    return value.length() >= max && DIGITS.matcher(value.subSequence(offset, max)).matches();
164	  }
165	
166	  static Map<String,String> parseNameValuePairs(String uri) {
167	    int paramStart = uri.indexOf('?');
168	    if (paramStart < 0) {
169	      return null;
170	    }
171	    Map<String,String> result = new HashMap<>(3);
172	    for (String keyValue : AMPERSAND.split(uri.substring(paramStart + 1))) {
173	      appendKeyValue(keyValue, result);
174	    }
175	    return result;
176	  }
177	
178	  private static void appendKeyValue(CharSequence keyValue, Map<String,String> result) {
179	    String[] keyValueTokens = EQUALS.split(keyValue, 2);
180	    if (keyValueTokens.length == 2) {
181	      String key = keyValueTokens[0];
182	      String value = keyValueTokens[1];
183	      try {
184	        value = urlDecode(value);
185	        result.put(key, value);
186	      } catch (IllegalArgumentException iae) {
187	        // continue; invalid data such as an escape like %0t
188	      }
189	    }
190	  }
191	
192	  static String urlDecode(String encoded) {
193	    try {
194	      return URLDecoder.decode(encoded, "UTF-8");
195	    } catch (UnsupportedEncodingException uee) {
196	      throw new IllegalStateException(uee); // can't happen
197	    }
198	  }
199	
200	  static String[] matchPrefixedField(String prefix, String rawText, char endChar, boolean trim) {
201	    List<String> matches = null;
202	    int i = 0;
203	    int max = rawText.length();
204	    while (i < max) {
205	      i = rawText.indexOf(prefix, i);
206	      if (i < 0) {
207	        break;
208	      }
209	      i += prefix.length(); // Skip past this prefix we found to start
210	      int start = i; // Found the start of a match here
211	      boolean more = true;
212	      while (more) {
213	        i = rawText.indexOf(endChar, i);
214	        if (i < 0) {
215	          // No terminating end character? uh, done. Set i such that loop terminates and break
216	          i = rawText.length();
217	          more = false;
218	        } else if (countPrecedingBackslashes(rawText, i) % 2 != 0) {
219	          // semicolon was escaped (odd count of preceding backslashes) so continue
220	          i++;
221	        } else {
222	          // found a match
223	          if (matches == null) {
224	            matches = new ArrayList<>(3); // lazy init
225	          }
226	          String element = unescapeBackslash(rawText.substring(start, i));
227	          if (trim) {
228	            element = element.trim();
229	          }
230	          if (!element.isEmpty()) {
231	            matches.add(element);
232	          }
233	          i++;
234	          more = false;
235	        }
236	      }
237	    }
238	    if (matches == null || matches.isEmpty()) {
239	      return null;
240	    }
241	    return matches.toArray(EMPTY_STR_ARRAY);
242	  }
243	
244	  private static int countPrecedingBackslashes(CharSequence s, int pos) {
245	    int count = 0;
246	    for (int i = pos - 1; i >= 0; i--) {
247	      if (s.charAt(i) == '\\') {
248	        count++;
249	      } else {
250	        break;
251	      }
252	    }
253	    return count;
254	  }
255	
256	  static String matchSinglePrefixedField(String prefix, String rawText, char endChar, boolean trim) {
257	    String[] matches = matchPrefixedField(prefix, rawText, endChar, trim);
258	    return matches == null ? null : matches[0];
259	  }
260	
261	}
