26	/**
27	 * Common string-related functions.
28	 *
29	 * @author Sean Owen
30	 * @author Alex Dupre
31	 */
32	public final class StringUtils {
33	
34	  private static final Charset PLATFORM_DEFAULT_ENCODING = Charset.defaultCharset();
35	  public static final Charset SHIFT_JIS_CHARSET;
36	  static {
37	    Charset sjisCharset;
38	    try {
39	      sjisCharset = Charset.forName("SJIS");
40	    } catch (UnsupportedCharsetException ucee) {
41	      // Can happen on JREs without lib/charsets.jar
42	      sjisCharset = null;
43	    }
44	    SHIFT_JIS_CHARSET = sjisCharset;
45	  }
46	  public static final Charset GB2312_CHARSET;
47	  static {
48	    Charset gb2312Charset;
49	    try {
50	      gb2312Charset = Charset.forName("GB2312");
51	    } catch (UnsupportedCharsetException ucee) {
52	      // Can happen on some embedded JREs?
53	      gb2312Charset = null;
54	    }
55	    GB2312_CHARSET = gb2312Charset;
56	  }
57	  private static final Charset EUC_JP;
58	  static {
59	    Charset eucJpCharset;
60	    try {
61	      eucJpCharset = Charset.forName("EUC_JP");
62	    } catch (UnsupportedCharsetException ucee) {
63	      // Can happen on JREs without lib/charsets.jar
64	      eucJpCharset = null;
65	    }
66	    EUC_JP = eucJpCharset;
67	  }
68	  private static final boolean ASSUME_SHIFT_JIS =
69	      (SHIFT_JIS_CHARSET != null && SHIFT_JIS_CHARSET.equals(PLATFORM_DEFAULT_ENCODING)) ||
70	      (EUC_JP != null && EUC_JP.equals(PLATFORM_DEFAULT_ENCODING));
71	
72	  // Retained for ABI compatibility with earlier versions
73	  public static final String SHIFT_JIS = "SJIS";
74	  public static final String GB2312 = "GB2312";
75	
76	  private StringUtils() { }
77	
78	  /**
79	   * @param bytes bytes encoding a string, whose encoding should be guessed
80	   * @param hints decode hints if applicable
81	   * @return name of guessed encoding; at the moment will only guess one of:
82	   *  "SJIS", "UTF8", "ISO8859_1", or the platform default encoding if none
83	   *  of these can possibly be correct
84	   */
85	  public static String guessEncoding(byte[] bytes, Map<DecodeHintType,?> hints) {
86	    Charset c = guessCharset(bytes, hints);
87	    if (c.equals(SHIFT_JIS_CHARSET)) {
88	      return "SJIS";
89	    }
90	    if (c.equals(StandardCharsets.UTF_8)) {
91	      return "UTF8";
92	    }
93	    if (c.equals(StandardCharsets.ISO_8859_1)) {
94	      return "ISO8859_1";
95	    }
96	    return c.name();
97	  }
98	
99	  /**
100	   * @param bytes bytes encoding a string, whose encoding should be guessed
101	   * @param hints decode hints if applicable
102	   * @return Charset of guessed encoding; at the moment will only guess one of:
103	   *  {@link #SHIFT_JIS_CHARSET}, {@link StandardCharsets#UTF_8},
104	   *  {@link StandardCharsets#ISO_8859_1}, {@link StandardCharsets#UTF_16},
105	   *  or the platform default encoding if
106	   *  none of these can possibly be correct
107	   */
108	  public static Charset guessCharset(byte[] bytes, Map<DecodeHintType,?> hints) {
109	    if (hints != null && hints.containsKey(DecodeHintType.CHARACTER_SET)) {
110	      return Charset.forName(hints.get(DecodeHintType.CHARACTER_SET).toString());
111	    }
112	
113	    // First try UTF-16, assuming anything with its BOM is UTF-16
114	    if (bytes.length > 2 &&
115	        ((bytes[0] == (byte) 0xFE && bytes[1] == (byte) 0xFF) ||
116	         (bytes[0] == (byte) 0xFF && bytes[1] == (byte) 0xFE))) {
117	      return StandardCharsets.UTF_16;
118	    }
119	
120	    // For now, merely tries to distinguish ISO-8859-1, UTF-8 and Shift_JIS,
121	    // which should be by far the most common encodings.
122	    int length = bytes.length;
123	    boolean canBeISO88591 = true;
124	    boolean canBeShiftJIS = SHIFT_JIS_CHARSET != null;
125	    boolean canBeUTF8 = true;
126	    int utf8BytesLeft = 0;
127	    int utf2BytesChars = 0;
128	    int utf3BytesChars = 0;
129	    int utf4BytesChars = 0;
130	    int sjisBytesLeft = 0;
131	    int sjisKatakanaChars = 0;
132	    int sjisCurKatakanaWordLength = 0;
133	    int sjisCurDoubleBytesWordLength = 0;
134	    int sjisMaxKatakanaWordLength = 0;
135	    int sjisMaxDoubleBytesWordLength = 0;
136	    int isoHighOther = 0;
137	
138	    boolean utf8bom = bytes.length > 3 &&
139	        bytes[0] == (byte) 0xEF &&
140	        bytes[1] == (byte) 0xBB &&
141	        bytes[2] == (byte) 0xBF;
142	
143	    for (int i = 0;
144	         i < length && (canBeISO88591 || canBeShiftJIS || canBeUTF8);
145	         i++) {
146	
147	      int value = bytes[i] & 0xFF;
148	
149	      // UTF-8 stuff
150	      if (canBeUTF8) {
151	        if (utf8BytesLeft > 0) {
152	          if ((value & 0x80) == 0) {
153	            canBeUTF8 = false;
154	          } else {
155	            utf8BytesLeft--;
156	          }
157	        } else if ((value & 0x80) != 0) {
158	          if ((value & 0x40) == 0) {
159	            canBeUTF8 = false;
160	          } else {
161	            utf8BytesLeft++;
162	            if ((value & 0x20) == 0) {
163	              utf2BytesChars++;
164	            } else {
165	              utf8BytesLeft++;
166	              if ((value & 0x10) == 0) {
167	                utf3BytesChars++;
168	              } else {
169	                utf8BytesLeft++;
170	                if ((value & 0x08) == 0) {
171	                  utf4BytesChars++;
172	                } else {
173	                  canBeUTF8 = false;
174	                }
175	              }
176	            }
177	          }
178	        }
179	      }
180	
181	      // ISO-8859-1 stuff
182	      if (canBeISO88591) {
183	        if (value > 0x7F && value < 0xA0) {
184	          canBeISO88591 = false;
185	        } else if (value > 0x9F && (value < 0xC0 || value == 0xD7 || value == 0xF7)) {
186	          isoHighOther++;
187	        }
188	      }
189	
190	      // Shift_JIS stuff
191	      if (canBeShiftJIS) {
192	        if (sjisBytesLeft > 0) {
193	          if (value < 0x40 || value == 0x7F || value > 0xFC) {
194	            canBeShiftJIS = false;
195	          } else {
196	            sjisBytesLeft--;
197	          }
198	        } else if (value == 0x80 || value == 0xA0 || value > 0xEF) {
199	          canBeShiftJIS = false;
200	        } else if (value > 0xA0 && value < 0xE0) {
201	          sjisKatakanaChars++;
202	          sjisCurDoubleBytesWordLength = 0;
203	          sjisCurKatakanaWordLength++;
204	          if (sjisCurKatakanaWordLength > sjisMaxKatakanaWordLength) {
205	            sjisMaxKatakanaWordLength = sjisCurKatakanaWordLength;
206	          }
207	        } else if (value > 0x7F) {
208	          sjisBytesLeft++;
209	          //sjisDoubleBytesChars++;
210	          sjisCurKatakanaWordLength = 0;
211	          sjisCurDoubleBytesWordLength++;
212	          if (sjisCurDoubleBytesWordLength > sjisMaxDoubleBytesWordLength) {
213	            sjisMaxDoubleBytesWordLength = sjisCurDoubleBytesWordLength;
214	          }
215	        } else {
216	          //sjisLowChars++;
217	          sjisCurKatakanaWordLength = 0;
218	          sjisCurDoubleBytesWordLength = 0;
219	        }
220	      }
221	    }
222	
223	    if (canBeUTF8 && utf8BytesLeft > 0) {
224	      canBeUTF8 = false;
225	    }
226	    if (canBeShiftJIS && sjisBytesLeft > 0) {
227	      canBeShiftJIS = false;
228	    }
229	
230	    // Easy -- if there is BOM or at least 1 valid not-single byte character (and no evidence it can't be UTF-8), done
231	    if (canBeUTF8 && (utf8bom || utf2BytesChars + utf3BytesChars + utf4BytesChars > 0)) {
232	      return StandardCharsets.UTF_8;
233	    }
234	    // Easy -- if assuming Shift_JIS or >= 3 valid consecutive not-ascii characters (and no evidence it can't be), done
235	    if (canBeShiftJIS && (ASSUME_SHIFT_JIS || sjisMaxKatakanaWordLength >= 3 || sjisMaxDoubleBytesWordLength >= 3)) {
236	      return SHIFT_JIS_CHARSET;
237	    }
238	    // Distinguishing Shift_JIS and ISO-8859-1 can be a little tough for short words. The crude heuristic is:
239	    // - If we saw
240	    //   - only two consecutive katakana chars in the whole text, or
241	    //   - at least 10% of bytes that could be "upper" not-alphanumeric Latin1,
242	    // - then we conclude Shift_JIS, else ISO-8859-1
243	    if (canBeISO88591 && canBeShiftJIS) {
244	      return (sjisMaxKatakanaWordLength == 2 && sjisKatakanaChars == 2) || isoHighOther * 10 >= length
245	          ? SHIFT_JIS_CHARSET : StandardCharsets.ISO_8859_1;
246	    }
247	
248	    // Otherwise, try in order ISO-8859-1, Shift JIS, UTF-8 and fall back to default platform encoding
249	    if (canBeISO88591) {
250	      return StandardCharsets.ISO_8859_1;
251	    }
252	    if (canBeShiftJIS) {
253	      return SHIFT_JIS_CHARSET;
254	    }
255	    if (canBeUTF8) {
256	      return StandardCharsets.UTF_8;
257	    }
258	    // Otherwise, we take a wild guess with platform encoding
259	    return PLATFORM_DEFAULT_ENCODING;
260	  }
261	
