89	  static DecoderResult decode(byte[] bytes) throws FormatException {
90	    BitSource bits = new BitSource(bytes);
91	    ECIStringBuilder result = new ECIStringBuilder(100);
92	    StringBuilder resultTrailer = new StringBuilder(0);
93	    List<byte[]> byteSegments = new ArrayList<>(1);
94	    Mode mode = Mode.ASCII_ENCODE;
95	    // Could look directly at 'bytes', if we're sure of not having to account for multi byte values
96	    boolean readerInit = (bytes.length > 0 && (bytes[0] & 0xFF) == 234);
97	    Set<Integer> fnc1Positions = new HashSet<>();
98	    int symbologyModifier;
99	    boolean isECIencoded = false;
100	    do {
101	      if (mode == Mode.ASCII_ENCODE) {
102	        mode = decodeAsciiSegment(bits, result, resultTrailer, fnc1Positions);
103	      } else {
104	        switch (mode) {
105	          case C40_ENCODE:
106	            decodeC40Segment(bits, result, fnc1Positions);
107	            break;
108	          case TEXT_ENCODE:
109	            decodeTextSegment(bits, result, fnc1Positions);
110	            break;
111	          case ANSIX12_ENCODE:
112	            decodeAnsiX12Segment(bits, result);
113	            break;
114	          case EDIFACT_ENCODE:
115	            decodeEdifactSegment(bits, result);
116	            break;
117	          case BASE256_ENCODE:
118	            decodeBase256Segment(bits, result, byteSegments);
119	            break;
120	          case ECI_ENCODE:

220	          case 240: // Latch to EDIFACT encodation
221	            return Mode.EDIFACT_ENCODE;
222	          case 241: // ECI Character
223	            return Mode.ECI_ENCODE;
224	          default:
225	            // Not to be used in ASCII encodation
226	            // but work around encoders that end with 254, latch back to ASCII
227	            if (oneByte != 254 || bits.available() != 0) {
228	              throw FormatException.getFormatInstance();
229	            }
230	            break;
231	        }
232	      }
233	    } while (bits.available() > 0);
234	    return Mode.ASCII_ENCODE;
