237	  /**
238	   * See ISO 16022:2006, 5.2.5 and Annex C, Table C.1
239	   */
240	  private static void decodeC40Segment(BitSource bits, ECIStringBuilder result, Set<Integer> fnc1positions)
241	      throws FormatException {
242	    // Three C40 values are encoded in a 16-bit value as
243	    // (1600 * C1) + (40 * C2) + C3 + 1
244	    // TODO(bbrown): The Upper Shift with C40 doesn't work in the 4 value scenario all the time
245	    boolean upperShift = false;
246	
247	    int[] cValues = new int[3];
248	    int shift = 0;
249	
250	    do {
251	      // If there is only one byte left then it will be encoded as ASCII
252	      if (bits.available() == 8) {
253	        return;
254	      }
255	      int firstByte = bits.readBits(8);
256	      if (firstByte == 254) {  // Unlatch codeword
257	        return;
258	      }
259	
260	      parseTwoBytes(firstByte, bits.readBits(8), cValues);
261	
262	      for (int i = 0; i < 3; i++) {
263	        int cValue = cValues[i];
264	        switch (shift) {
265	          case 0:
266	            if (cValue < 3) {
267	              shift = cValue + 1;
268	            } else if (cValue < C40_BASIC_SET_CHARS.length) {
269	              char c40char = C40_BASIC_SET_CHARS[cValue];
270	              if (upperShift) {
271	                result.append((char) (c40char + 128));
272	                upperShift = false;
273	              } else {
274	                result.append(c40char);
275	              }
276	            } else {
277	              throw FormatException.getFormatInstance();
278	            }
279	            break;
280	          case 1:
281	            if (upperShift) {
282	              result.append((char) (cValue + 128));
283	              upperShift = false;
284	            } else {
285	              result.append((char) cValue);
286	            }
287	            shift = 0;
288	            break;
289	          case 2:
290	            if (cValue < C40_SHIFT2_SET_CHARS.length) {
291	              char c40char = C40_SHIFT2_SET_CHARS[cValue];
292	              if (upperShift) {
293	                result.append((char) (c40char + 128));
294	                upperShift = false;
295	              } else {
296	                result.append(c40char);
297	              }
298	            } else {
299	              switch (cValue) {
300	                case 27: // FNC1
301	                  fnc1positions.add(result.length());
302	                  result.append((char) 29); // translate as ASCII 29
303	                  break;
304	                case 30: // Upper Shift
305	                  upperShift = true;
306	                  break;
307	                default:
308	                  throw FormatException.getFormatInstance();
309	              }
310	            }
311	            shift = 0;
312	            break;
313	          case 3:
314	            if (upperShift) {
315	              result.append((char) (cValue + 224));
316	              upperShift = false;
317	            } else {
318	              result.append((char) (cValue + 96));
319	            }
320	            shift = 0;
321	            break;
322	          default:
323	            throw FormatException.getFormatInstance();
324	        }
325	      }
326	    } while (bits.available() > 0);
327	  }
