486	  /**
487	   * See ISO 16022:2006, 5.2.8 and Annex C Table C.3
488	   */
489	  private static void decodeEdifactSegment(BitSource bits, ECIStringBuilder result) {
490	    do {
491	      // If there is only two or less bytes left then it will be encoded as ASCII
492	      if (bits.available() <= 16) {
493	        return;
494	      }
495	
496	      for (int i = 0; i < 4; i++) {
497	        int edifactValue = bits.readBits(6);
498	
499	        // Check for the unlatch character
500	        if (edifactValue == 0x1F) {  // 011111
501	          // Read rest of byte, which should be 0, and stop
502	          int bitsLeft = 8 - bits.getBitOffset();
503	          if (bitsLeft != 8) {
504	            bits.readBits(bitsLeft);
505	          }
506	          return;
507	        }
508	
509	        if ((edifactValue & 0x20) == 0) {  // no 1 in the leading (6th) bit
510	          edifactValue |= 0x40;  // Add a leading 01 to the 6 bit binary value
511	        }
512	        result.append((char) edifactValue);
513	      }
514	    } while (bits.available() > 0);
515	  }
