517	  /**
518	   * See ISO 16022:2006, 5.2.9 and Annex B, B.2
519	   */
520	  private static void decodeBase256Segment(BitSource bits,
521	                                           ECIStringBuilder result,
522	                                           Collection<byte[]> byteSegments)
523	      throws FormatException {
524	    // Figure out how long the Base 256 Segment is.
525	    int codewordPosition = 1 + bits.getByteOffset(); // position is 1-indexed
526	    int d1 = unrandomize255State(bits.readBits(8), codewordPosition++);
527	    int count;
528	    if (d1 == 0) {  // Read the remainder of the symbol
529	      count = bits.available() / 8;
530	    } else if (d1 < 250) {
531	      count = d1;
532	    } else {
533	      if (bits.available() < 8) {
534	        throw FormatException.getFormatInstance();
535	      }
536	      count = 250 * (d1 - 249) + unrandomize255State(bits.readBits(8), codewordPosition++);
537	    }
538	
539	    // We're seeing NegativeArraySizeException errors from users.
540	    if (count < 0) {
541	      throw FormatException.getFormatInstance();
542	    }
543	
544	    byte[] bytes = new byte[count];
545	    for (int i = 0; i < count; i++) {
546	      // Have seen this particular error in the wild, such as at
547	      // http://www.bcgen.com/demo/IDAutomationStreamingDataMatrix.aspx?MODE=3&D=Fred&PFMT=3&PT=F&X=0.3&O=0&LM=0.2
548	      if (bits.available() < 8) {
549	        throw FormatException.getFormatInstance();
550	      }
551	      bytes[i] = (byte) unrandomize255State(bits.readBits(8), codewordPosition++);
552	    }
553	    byteSegments.add(bytes);
554	    result.append(new String(bytes, StandardCharsets.ISO_8859_1));
555	  }
