192	  /**
193	   * Parses a string as a date. RFC 2445 allows the start and end fields to be of type DATE (e.g. 20081021)
194	   * or DATE-TIME (e.g. 20081021T123000 for local time, or 20081021T123000Z for UTC).
195	   *
196	   * @param when The string to parse
197	   * @throws ParseException if not able to parse as a date
198	   */
199	  private static long parseDate(String when) throws ParseException {
200	    if (!DATE_TIME.matcher(when).matches()) {
201	      throw new ParseException(when, 0);
202	    }
203	    if (when.length() == 8) {
204	      // Show only year/month/day
205	      DateFormat format = new SimpleDateFormat("yyyyMMdd", Locale.ENGLISH);
206	      // For dates without a time, for purposes of interacting with Android, the resulting timestamp
207	      // needs to be midnight of that day in GMT. See:
208	      // http://code.google.com/p/android/issues/detail?id=8330
209	      format.setTimeZone(TimeZone.getTimeZone("GMT"));
210	      return format.parse(when).getTime();
211	    }
212	    // The when string can be local time, or UTC if it ends with a Z
213	    if (when.length() == 16 && when.charAt(15) == 'Z') {
214	      long milliseconds = parseDateTimeString(when.substring(0, 15));
215	      Calendar calendar = new GregorianCalendar();
216	      // Account for time zone difference
217	      milliseconds += calendar.get(Calendar.ZONE_OFFSET);
218	      // Might need to correct for daylight savings time, but use target time since
219	      // now might be in DST but not then, or vice versa
220	      calendar.setTime(new Date(milliseconds));
221	      return milliseconds + calendar.get(Calendar.DST_OFFSET);
222	    }
223	    return parseDateTimeString(when);
224	  }
