226	  private static String format(boolean allDay, long date) {
227	    if (date < 0L) {
228	      return null;
229	    }
230	    DateFormat format = allDay
231	        ? DateFormat.getDateInstance(DateFormat.MEDIUM)
232	        : DateFormat.getDateTimeInstance(DateFormat.MEDIUM, DateFormat.MEDIUM);
233	    return format.format(date);
234	  }
