236	  private static long parseDurationMS(CharSequence durationString) {
237	    if (durationString == null) {
238	      return -1L;
239	    }
240	    Matcher m = RFC2445_DURATION.matcher(durationString);
241	    if (!m.matches()) {
242	      return -1L;
243	    }
244	    long durationMS = 0L;
245	    for (int i = 0; i < RFC2445_DURATION_FIELD_UNITS.length; i++) {
246	      String fieldValue = m.group(i + 1);
247	      if (fieldValue != null) {
248	        durationMS += RFC2445_DURATION_FIELD_UNITS[i] * Integer.parseInt(fieldValue);
249	      }
250	    }
251	    return durationMS;
252	  }
253	
254	  private static long parseDateTimeString(String dateTimeString) throws ParseException {
255	    DateFormat format = new SimpleDateFormat("yyyyMMdd'T'HHmmss", Locale.ENGLISH);
256	    return format.parse(dateTimeString).getTime();
257	  }
