89	  static DecoderResult decode(byte[] bytes, int mode) throws FormatException {
90	    StringBuilder result = new StringBuilder(144);
91	    switch (mode) {
92	      case 2:
93	      case 3:
94	        String postcode;
95	        if (mode == 2) {
96	          int pc = getPostCode2(bytes);
97	          int ps2Length = getPostCode2Length(bytes);
98	          if (ps2Length > 10) {
99	            throw FormatException.getFormatInstance();
100	          }
101	          NumberFormat df = new DecimalFormat("0000000000".substring(0, ps2Length),
102	              DecimalFormatSymbols.getInstance(Locale.ROOT));
103	          postcode = df.format(pc);
104	        } else {
105	          postcode = getPostCode3(bytes);
106	        }
107	        NumberFormat threeDigits = new DecimalFormat("000", DecimalFormatSymbols.getInstance(Locale.ROOT));
108	        String country = threeDigits.format(getCountry(bytes));
109	        String service = threeDigits.format(getServiceClass(bytes));
110	        result.append(getMessage(bytes, 10, 84));
111	        if (result.toString().startsWith("[)>" + RS + "01" + GS)) {
112	          if (result.length() < 9) {
113	            throw FormatException.getFormatInstance();
114	          }
115	          result.insert(9, postcode + GS + country + GS + service + GS);
116	        } else {
117	          result.insert(0, postcode + GS + country + GS + service + GS);
118	        }
119	        break;
120	      case 4:
121	        result.append(getMessage(bytes, 1, 93));
122	        break;
123	      case 5:
124	        result.append(getMessage(bytes, 1, 77));
125	        break;
126	    }
127	    return new DecoderResult(bytes, result.toString(), null, String.valueOf(mode));
128	  }
