333	  /**
334	   * <p>After a horizontal scan finds a potential finder pattern, this method
335	   * "cross-checks" by scanning down vertically through the center of the possible
336	   * finder pattern to see if the same proportion is detected.</p>
337	   *
338	   * @param startI row where a finder pattern was detected
339	   * @param centerJ center of the section that appears to cross a finder pattern
340	   * @param maxCount maximum reasonable number of modules that should be
341	   * observed in any reading state, based on the results of the horizontal scan
342	   * @return vertical center of finder pattern, or {@link Float#NaN} if not found
343	   */
344	  private float crossCheckVertical(int startI, int centerJ, int maxCount,
345	      int originalStateCountTotal) {
346	    BitMatrix image = this.image;
347	
348	    int maxI = image.getHeight();
349	    int[] stateCount = getCrossCheckStateCount();
350	
351	    // Start counting up from center
352	    int i = startI;
353	    while (i >= 0 && image.get(centerJ, i)) {
354	      stateCount[2]++;
355	      i--;
356	    }
357	    if (i < 0) {
358	      return Float.NaN;
359	    }
360	    while (i >= 0 && !image.get(centerJ, i) && stateCount[1] <= maxCount) {
361	      stateCount[1]++;
362	      i--;
363	    }
364	    // If already too many modules in this state or ran off the edge:
365	    if (i < 0 || stateCount[1] > maxCount) {
366	      return Float.NaN;
367	    }
368	    while (i >= 0 && image.get(centerJ, i) && stateCount[0] <= maxCount) {
369	      stateCount[0]++;
370	      i--;
371	    }
372	    if (stateCount[0] > maxCount) {
373	      return Float.NaN;
374	    }
375	
376	    // Now also count down from center
377	    i = startI + 1;
378	    while (i < maxI && image.get(centerJ, i)) {
379	      stateCount[2]++;
380	      i++;
381	    }
382	    if (i == maxI) {
383	      return Float.NaN;
384	    }
385	    while (i < maxI && !image.get(centerJ, i) && stateCount[3] < maxCount) {
386	      stateCount[3]++;
387	      i++;
388	    }
389	    if (i == maxI || stateCount[3] >= maxCount) {
390	      return Float.NaN;
391	    }
392	    while (i < maxI && image.get(centerJ, i) && stateCount[4] < maxCount) {
393	      stateCount[4]++;
394	      i++;
395	    }
396	    if (stateCount[4] >= maxCount) {
397	      return Float.NaN;
398	    }
399	
400	    // If we found a finder-pattern-like section, but its size is more than 40% different than
401	    // the original, assume it's a false positive
402	    int stateCountTotal = stateCount[0] + stateCount[1] + stateCount[2] + stateCount[3] +
403	        stateCount[4];
404	    if (5 * Math.abs(stateCountTotal - originalStateCountTotal) >= 2 * originalStateCountTotal) {
405	      return Float.NaN;
406	    }
407	
408	    return foundPatternCross(stateCount) ? centerFromEnd(stateCount, i) : Float.NaN;
409	  }
