17	package com.google.zxing.datamatrix.encoder;
18	
19	final class X12Encoder extends C40Encoder {
20	
21	  @Override
22	  public int getEncodingMode() {
23	    return HighLevelEncoder.X12_ENCODATION;
24	  }
25	
26	  @Override
27	  public void encode(EncoderContext context) {
28	    //step C
29	    StringBuilder buffer = new StringBuilder();
30	    while (context.hasMoreCharacters()) {
31	      char c = context.getCurrentChar();
32	      context.pos++;
33	
34	      encodeChar(c, buffer);
35	
36	      int count = buffer.length();
37	      if ((count % 3) == 0) {
38	        writeNextTriplet(context, buffer);
39	
40	        int newMode = HighLevelEncoder.lookAheadTest(context.getMessage(), context.pos, getEncodingMode());
41	        if (newMode != getEncodingMode()) {
42	          // Return to ASCII encodation, which will actually handle latch to new mode
43	          context.signalEncoderChange(HighLevelEncoder.ASCII_ENCODATION);
44	          break;
45	        }
46	      }
47	    }
48	    handleEOD(context, buffer);
49	  }
50	
51	  @Override
52	  int encodeChar(char c, StringBuilder sb) {
53	    switch (c) {
54	      case '\r':
55	        sb.append('\0');
56	        break;
57	      case '*':
58	        sb.append('\1');
59	        break;
60	      case '>':
61	        sb.append('\2');
62	        break;
63	      case ' ':
64	        sb.append('\3');
65	        break;
66	      default:
67	        if (c >= '0' && c <= '9') {
68	          sb.append((char) (c - 48 + 4));
69	        } else if (c >= 'A' && c <= 'Z') {
70	          sb.append((char) (c - 65 + 14));
71	        } else {
72	          HighLevelEncoder.illegalCharacter(c);
73	        }
74	        break;
75	    }
76	    return 1;
77	  }
78	
79	  @Override
80	  void handleEOD(EncoderContext context, StringBuilder buffer) {
81	    context.updateSymbolInfo();
82	    int available = context.getSymbolInfo().getDataCapacity() - context.getCodewordCount();
83	    int count = buffer.length();
84	    context.pos -= count;
85	    if (context.getRemainingCharacters() > 1 || available > 1 ||
86	        context.getRemainingCharacters() != available) {
87	      context.writeCodeword(HighLevelEncoder.X12_UNLATCH);
88	    }
89	    if (context.getNewEncoding() < 0) {
90	      context.signalEncoderChange(HighLevelEncoder.ASCII_ENCODATION);
91	    }
92	  }
93	}
