60	  @Override
61	  public void encode(EncoderContext context) {
62	    //step C
63	    StringBuilder buffer = new StringBuilder();
64	    while (context.hasMoreCharacters()) {
65	      char c = context.getCurrentChar();
66	      context.pos++;
67	
68	      int lastCharSize = encodeChar(c, buffer);
69	
70	      int unwritten = (buffer.length() / 3) * 2;
71	
72	      int curCodewordCount = context.getCodewordCount() + unwritten;
73	      context.updateSymbolInfo(curCodewordCount);
74	      int available = context.getSymbolInfo().getDataCapacity() - curCodewordCount;
75	
76	      if (!context.hasMoreCharacters()) {
77	        //Avoid having a single C40 value in the last triplet
78	        StringBuilder removed = new StringBuilder();
79	        if ((buffer.length() % 3) == 2 && available != 2) {
80	          lastCharSize = backtrackOneCharacter(context, buffer, removed, lastCharSize);
81	        }
82	        while ((buffer.length() % 3) == 1 && (lastCharSize > 3 || available != 1)) {
83	          lastCharSize = backtrackOneCharacter(context, buffer, removed, lastCharSize);
84	        }
85	        break;
86	      }
87	
88	      int count = buffer.length();
89	      if ((count % 3) == 0) {
90	        int newMode = HighLevelEncoder.lookAheadTest(context.getMessage(), context.pos, getEncodingMode());
91	        if (newMode != getEncodingMode()) {
92	          // Return to ASCII encodation, which will actually handle latch to new mode
93	          context.signalEncoderChange(HighLevelEncoder.ASCII_ENCODATION);
94	          break;
95	        }
96	      }
97	    }
98	    handleEOD(context, buffer);
99	  }
