270	  // Return the position of the most significant bit set (to one) in the "value". The most
271	  // significant bit is position 32. If there is no bit set, return 0. Examples:
272	  // - findMSBSet(0) => 0
273	  // - findMSBSet(1) => 1
274	  // - findMSBSet(255) => 8
275	  static int findMSBSet(int value) {
276	    return 32 - Integer.numberOfLeadingZeros(value);
277	  }
278	
279	  // Calculate BCH (Bose-Chaudhuri-Hocquenghem) code for "value" using polynomial "poly". The BCH
280	  // code is used for encoding type information and version information.
281	  // Example: Calculation of version information of 7.
282	  // f(x) is created from 7.
283	  //   - 7 = 000111 in 6 bits
284	  //   - f(x) = x^2 + x^1 + x^0
285	  // g(x) is given by the standard (p. 67)
286	  //   - g(x) = x^12 + x^11 + x^10 + x^9 + x^8 + x^5 + x^2 + 1
287	  // Multiply f(x) by x^(18 - 6)
288	  //   - f'(x) = f(x) * x^(18 - 6)
289	  //   - f'(x) = x^14 + x^13 + x^12
290	  // Calculate the remainder of f'(x) / g(x)
291	  //         x^2
292	  //         __________________________________________________
293	  //   g(x) )x^14 + x^13 + x^12
294	  //         x^14 + x^13 + x^12 + x^11 + x^10 + x^7 + x^4 + x^2
295	  //         --------------------------------------------------
296	  //                              x^11 + x^10 + x^7 + x^4 + x^2
297	  //
298	  // The remainder is x^11 + x^10 + x^7 + x^4 + x^2
299	  // Encode it in binary: 110010010100
300	  // The return value is 0xc94 (1100 1001 0100)
301	  //
302	  // Since all coefficients in the polynomials are 1 or 0, we can do the calculation by bit
303	  // operations. We don't care if coefficients are positive or negative.
304	  static int calculateBCHCode(int value, int poly) {
305	    if (poly == 0) {
306	      throw new IllegalArgumentException("0 polynomial");
307	    }
308	    // If poly is "1 1111 0010 0101" (version info poly), msbSetInPoly is 13. We'll subtract 1
309	    // from 13 to make it 12.
310	    int msbSetInPoly = findMSBSet(poly);
311	    value <<= msbSetInPoly - 1;
312	    // Do the division business using exclusive-or operations.
313	    while (findMSBSet(value) >= msbSetInPoly) {
314	      value ^= poly << (findMSBSet(value) - msbSetInPoly);
315	    }
316	    // Now the "value" is the remainder (i.e. the BCH code)
317	    return value;
318	  }
