import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Random;

/** Differential test for DataMatrix DecodedBitStreamParser.decode(byte[]): original vs refactored. */
public final class DmDiff {

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  static Method decodeMethod(ClassLoader cl) throws Exception {
    Class<?> c = Class.forName("com.google.zxing.datamatrix.decoder.DecodedBitStreamParser", true, cl);
    Method m = c.getDeclaredMethod("decode", byte[].class);
    m.setAccessible(true);
    return m;
  }

  /** Canonical signature of decode outcome: result text (+ raw bytes len) or exception class. */
  static String run(Method decode, byte[] bytes) {
    try {
      Object dr = decode.invoke(null, (Object) bytes);
      Class<?> drc = dr.getClass();
      String text = (String) drc.getMethod("getText").invoke(dr);
      // include a few more fields to be thorough
      Object ecLevel = drc.getMethod("getECLevel").invoke(dr);
      int symb = (int) drc.getMethod("getSymbologyModifier").invoke(dr);
      return "OK|len=" + text.length() + "|text=" + text + "|ec=" + ecLevel + "|symb=" + symb;
    } catch (Throwable t) {
      Throwable c = (t.getCause() != null) ? t.getCause() : t;
      return "EX|" + c.getClass().getName();
    }
  }

  public static void main(String[] args) throws Exception {
    Method oldD = decodeMethod(loader(args[0]));
    Method newD = decodeMethod(loader(args[1]));

    Random r = new Random(7);
    long total = 0;
    long ok = 0;
    long mism = 0;

    // Scenario sets: prefix drives the mode. 230=C40, 239=Text, 238=X12, -1=pure random.
    int[] prefixes = { 230, 239, 238, -1 };
    for (int scenario = 0; scenario < prefixes.length; scenario++) {
      int prefix = prefixes[scenario];
      int iters = (prefix == -1) ? 150000 : 350000;
      for (int k = 0; k < iters; k++) {
        int len = 1 + r.nextInt(14);
        byte[] bytes = new byte[len + (prefix == -1 ? 0 : 1)];
        int off = 0;
        if (prefix != -1) {
          bytes[0] = (byte) prefix;
          off = 1;
        }
        for (int i = 0; i < len; i++) {
          bytes[off + i] = (byte) r.nextInt(256);
        }
        String a = run(oldD, bytes);
        String b = run(newD, bytes);
        total++;
        if (a.startsWith("OK")) {
          ok++;
        }
        if (!a.equals(b)) {
          mism++;
          if (mism <= 20) {
            StringBuilder hex = new StringBuilder();
            for (byte x : bytes) {
              hex.append(String.format("%02x ", x & 0xFF));
            }
            System.out.println("MISMATCH prefix=" + prefix + " bytes=[" + hex.toString().trim() + "]");
            System.out.println("  old: " + a);
            System.out.println("  new: " + b);
          }
        }
      }
    }
    System.out.println("----");
    System.out.println("Total comparisons:    " + total);
    System.out.println("Successful decodes:    " + ok);
    System.out.println("Mismatches:           " + mism);
    System.out.println(mism == 0 ? "RESULT: IDENTICAL BEHAVIOR" : "RESULT: DIFFERENCES FOUND");
  }
}

